function Badge({status, children}) { const value=STATUS[status]||[status,'gray']; return <span className={`badge ${value[1]}`}>{children||value[0]}</span>; }
function Button({children, icon, className='', variant='primary', ...props}) { return <button className={`btn ${variant} ${className}`} {...props}>{icon&&<Icon name={icon} size={17}/>}<span>{children}</span></button>; }
function Field({label,children,hint}) {
  const id=React.useId();
  return <div className="field"><label htmlFor={id}>{label}</label>{React.isValidElement(children)?React.cloneElement(children,{id,'aria-describedby':hint?`${id}-hint`:undefined}):children}{hint&&<small id={`${id}-hint`}>{hint}</small>}</div>;
}
function Empty({text='暂无数据',detail='数据产生后将在这里展示。'}) { return <div className="empty"><span><Icon name="layers" size={30}/></span><strong>{text}</strong><p>{detail}</p></div>; }
function Loading(){return <div className="loading"><span className="spinner"/>正在加载数据…</div>;}
function Modal({title,description,children,onClose,wide=false}) {
  const dialogRef=useRef(null), closeRef=useRef(onClose); closeRef.current=onClose;
  useEffect(()=>{ const before=document.activeElement; dialogRef.current?.focus(); const key=e=>{if(e.key==='Escape')closeRef.current(); if(e.key==='Tab'){const items=dialogRef.current?.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]'); if(!items?.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}; document.addEventListener('keydown',key);document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',key);document.body.style.overflow='';before?.focus();};},[]);
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section className={`modal ${wide?'wide':''}`} role="dialog" aria-modal="true" aria-labelledby="modal-title" tabIndex={-1} ref={dialogRef}><div className="modal-heading"><div><h2 id="modal-title">{title}</h2>{description&&<p>{description}</p>}</div><button className="icon-btn" aria-label="关闭" onClick={onClose}><Icon name="close"/></button></div>{children}</section></div>;
}
function useData(loader,deps=[]) {
  const [data,setData]=useState(null),[loading,setLoading]=useState(true),[error,setError]=useState('');
  const load=useCallback(async()=>{setLoading(true);setError('');try{setData(await loader());}catch(e){setError(e.message);}finally{setLoading(false);}},deps);
  useEffect(()=>{load();},[load]);return {data,loading,error,reload:load};
}
function DataState({state,children}){return state.loading?<Loading/>:state.error?<div className="error-panel"><Icon name="message"/><span>{state.error}</span><Button variant="secondary" onClick={state.reload}>重试</Button></div>:children;}
function FormError({error}){return error?<div className="form-error" role="alert">{error}</div>:null;}
function date(value,withTime=false){if(!value)return '—';let d=new Date(value);return isNaN(d)?String(value):d.toLocaleString('zh-CN',withTime?{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}:{year:'numeric',month:'2-digit',day:'2-digit'});}
const num=value=>Number(value||0).toLocaleString('zh-CN');
const percent=value=>`${Number(value||0).toFixed(1)}%`;
function Table({headers,children,empty}) {
  const rows=React.Children.toArray(children), pageSize=50;
  const [page,setPage]=useState(0);
  const signature=rows.map(row=>row.key).join('|');
  useEffect(()=>setPage(0),[signature]);
  const pages=Math.max(1,Math.ceil(rows.length/pageSize)), current=Math.min(page,pages-1);
  const shown=rows.length>pageSize?rows.slice(current*pageSize,(current+1)*pageSize):rows;
  return <div className="data-table"><div className="table-wrap"><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{shown}</tbody></table>{empty&&<Empty/>}</div>{rows.length>pageSize&&<nav className="table-pagination" aria-label="表格分页"><span>第 {current*pageSize+1}–{Math.min((current+1)*pageSize,rows.length)} 项，共 {num(rows.length)} 项</span><div><Button variant="secondary" aria-label="上一页表格" disabled={current===0} onClick={()=>setPage(current-1)}>上一页</Button><select aria-label="表格页码" value={current} onChange={event=>setPage(Number(event.target.value))}>{Array.from({length:pages},(_,i)=><option key={i} value={i}>第 {i+1} 页</option>)}</select><Button variant="secondary" aria-label="下一页表格" disabled={current===pages-1} onClick={()=>setPage(current+1)}>下一页</Button></div></nav>}</div>;
}

function Login({onLogin}) {
  const [form,setForm]=useState({username:'',password:''}),[error,setError]=useState(''),[busy,setBusy]=useState(false);
  const submit=async e=>{e.preventDefault();setBusy(true);setError('');try{const payload={username:form.username.trim(),password:form.password};const data=await post('/auth/login',payload);if(data.user.role==='student'){storeSession(data);try{await post('/auth/logout',{refresh_token:data.refresh_token});}finally{clearSession();}throw new Error('请使用 Android 学生端登录；此入口供教师和管理员使用。');}storeSession(data);onLogin(data.user);}catch(e){setError(e.status===429?'登录尝试过多，请暂停重试，稍后再登录。':e.status===401?'账号或密码不正确，请检查后重试。':e.message);}finally{setBusy(false);}};
  return <main className="login-page"><section className="login-story"><div className="brand"><span className="brand-icon"><Icon name="book" size={27}/></span><div>职考通<small>ZHIKAOTONG</small></div></div><div className="login-intro"><span className="eyebrow">让每一份努力，都被看见</span><h1>更有方向的备考，<br/>更有温度的教学。</h1><p>连接学生、教师与优质题库，<br/>把学习的每一步，变成清晰可见的成长。</p><div className="login-features"><span><Icon name="check" size={16}/>班级协同管理</span><span><Icon name="check" size={16}/>学习数据洞察</span><span><Icon name="check" size={16}/>题库便捷管理</span></div></div><div className="story-art" aria-hidden="true"><div className="orbit o1"/><div className="orbit o2"/><div className="art-card"><div className="mini-label"><span/>每一步，向目标靠近</div><div className="art-bars">{[38,60,46,78,68,94,85].map((h,i)=><i key={i} style={{height:h+'%'}}/>)}</div><div className="art-bottom"><span>持续练习</span><strong>持续进步 ↗</strong></div></div><div className="floating-check"><Icon name="check" size={26}/></div></div><footer>专注职业教育 · 服务每一次成长</footer></section><section className="login-form-section"><div className="login-form"><div className="secure-label"><Icon name="shield" size={16}/>教学管理平台</div><h2>欢迎回来</h2><p>登录账号，开始今天的教学工作。</p><form onSubmit={submit}><Field label="账号"><input autoComplete="username" required value={form.username} onChange={e=>setForm({...form,username:e.target.value})} placeholder="请输入教师或管理员账号"/></Field><Field label="密码"><input type="password" autoComplete="current-password" required value={form.password} onChange={e=>setForm({...form,password:e.target.value})} placeholder="请输入密码"/></Field><FormError error={error}/><Button className="login-submit" disabled={busy}>{busy?'正在登录…':'登录工作台'}<Icon name="arrow" size={18}/></Button></form><div className="login-notice"><Icon name="lock" size={17}/><p>账号由学校统一开通，不开放公开注册。<br/>如需登录帮助，请联系学校管理员。</p></div></div><div className="login-footer">职考通 v0.8.7 · 单校教学与备考管理平台</div></section></main>;
}

function PasswordForm({onDone,required=false}) {
  const [form,setForm]=useState({old_password:'',new_password:'',confirm:''}),[error,setError]=useState(''),[busy,setBusy]=useState(false);
  const submit=async e=>{e.preventDefault();if(form.new_password!==form.confirm){setError('两次输入的新密码不一致。');return;}setBusy(true);setError('');try{await post('/auth/password',{old_password:form.old_password,new_password:form.new_password});onDone();}catch(e){setError(e.message);}finally{setBusy(false);}};
  return <form onSubmit={submit}><p className="form-intro">{required?'首次登录请先修改初始密码。修改后需要重新登录。':'修改密码后，其他设备会退出登录。'}</p><Field label="当前密码"><input type="password" autoComplete="current-password" required value={form.old_password} onChange={e=>setForm({...form,old_password:e.target.value})}/></Field><Field label="新密码" hint="至少 10 位，包含大写、小写字母和数字。"><input type="password" autoComplete="new-password" minLength={10} required value={form.new_password} onChange={e=>setForm({...form,new_password:e.target.value})}/></Field><Field label="确认新密码"><input type="password" autoComplete="new-password" minLength={10} required value={form.confirm} onChange={e=>setForm({...form,confirm:e.target.value})}/></Field><FormError error={error}/><div className="form-actions"><Button disabled={busy}>{busy?'正在保存…':'保存新密码'}</Button></div></form>;
}

