  const admin=user.role==='admin';
  const groups=state.data?.config?.subject_groups||[];
  const classes=(state.data?.classes||[]).filter(c=>c.name.includes(q));
  const availableStudents=memberCandidates.filter(u=>u.enabled!==false&&!members?.some(m=>m.id===u.id&&!['left','rejected'].includes(m.status)));
  useEffect(()=>{
    const query=memberSearch.trim();let current=true;
    setMemberCandidates([]);setMemberUserId('');setMemberSearchError('');setMemberSearchLoading(false);
    if(!admin||modal!=='members'||!memberSearchOpen||selected?.archived||!query)return;
    setMemberSearchLoading(true);
    const timer=setTimeout(()=>{api(`/management/users?role=student&q=${encodeURIComponent(query)}&limit=50`).then(rows=>{if(current)setMemberCandidates(rows);}).catch(failure=>{if(current)setMemberSearchError(failure.message);}).finally(()=>{if(current)setMemberSearchLoading(false);});},300);
    return()=>{current=false;clearTimeout(timer);};
  },[admin,modal,memberSearchOpen,memberSearch,selected?.id,selected?.archived]);
  const openCreate=()=>{setDeleted(false);setForm({name:'',term:'2026—2027 学年',subject_group_id:groups[0]?.id||'',teacher_id:admin?(state.data?.users||[]).find(u=>u.role==='teacher')?.id||'':user.id});setError('');setModal('create');};
  const showMembers=async c=>{const request=++membersRequest.current;selectedClassRef.current=c.id;setSelected(c);setMembers(null);setMemberUserId('');setMemberSearchOpen(false);setMemberSearch('');setMemberCandidates([]);setModal('members');setError('');try{const loaded=await api(`/management/classes/${c.id}/members`);if(request===membersRequest.current&&selectedClassRef.current===c.id)setMembers(loaded);}catch(e){if(request===membersRequest.current&&selectedClassRef.current===c.id)setError(e.message);}};
  const refreshMembers=async()=>{const classId=selected.id,request=++membersRequest.current;const refreshed=await api(`/management/classes/${classId}/members`);if(request!==membersRequest.current||selectedClassRef.current!==classId)return;setMembers(refreshed);await state.reload();};
  const closeMembers=()=>{if(busy)return;membersRequest.current++;selectedClassRef.current=null;setModal(null);};
  const create=async e=>{e.preventDefault();setBusy(true);setError('');try{await post('/management/classes',form);setModal(null);notify('班级已创建。');await state.reload();}catch(e){setError(e.message);}finally{setBusy(false);}};
  const updateMember=async(m,status)=>{
    if(status==='left'&&!window.confirm(`确定将 ${m.name||m.username} 移出班级？历史成绩会保留。`))return;
    setBusy(true);setError('');
    try{await patch(`/management/memberships/${m.membership_id}`,{status});notify(status==='active'&&admin?'学生已成为正式成员。':'成员状态已更新。');await refreshMembers();}catch(e){setError(e.message);}finally{setBusy(false);}
  };
  const addMember=async e=>{
    e.preventDefault();if(!memberUserId)return;setBusy(true);setError('');
    try{await post(`/management/classes/${selected.id}/members`,{user_id:memberUserId});setMemberUserId('');notify('学生已直接加入班级。');await refreshMembers();}catch(e){setError(e.message);}finally{setBusy(false);}
  };
  const archive=async c=>{if(!window.confirm(`确定归档“${c.name}”？归档后班级只读。`))return;try{await patch(`/management/classes/${c.id}`,{archived:true});notify('班级已归档。');await state.reload();}catch(e){notify(e.message,'error');}};
  return <>
    <PageHeader kicker="教学管理 / CLASSES" title="班级管理" description="把每一位学生，放在合适的成长路径上。"><Button icon="plus" onClick={openCreate}>创建班级</Button></PageHeader>
    {admin&&<RemovalViews kind="classes" deleted={deleted} onChange={setDeleted}/>}
    <div className="class-overview"><div><strong>{num(classes.filter(c=>deleted||!c.archived).length)}</strong><span>{deleted?'已删除班级':'教学中班级'}</span></div><div><strong>{num(classes.reduce((s,c)=>s+Number(c.member_count||0),0))}</strong><span>班级成员</span></div><div><strong>{num(classes.reduce((s,c)=>s+Number(c.pending_count||0),0))}</strong><span>{admin?'待处理成员':'待确认 / 待审批'}</span></div><SearchInput value={q} onChange={setQ} placeholder="搜索班级名称"/></div>
    <DataState state={state}><div className="class-grid">{classes.map((c,i)=><section key={c.id} className="class-card"><div className="class-card-top"><span className={`class-symbol c${i%3}`}><Icon name="school" size={28}/></span><Badge status={deleted||c.archived?'offline':'active'}>{deleted?'已删除':c.archived?'已归档':'教学中'}</Badge></div><h2>{c.name}</h2><p>{c.term||'未设置学期'}</p><div className="class-meta"><span><Icon name="contact" size={15}/>{c.teacher_name||'未分配教师'}</span><span>{groups.find(g=>g.id===c.subject_group_id)?.name||'专业未设置'}</span></div><div className="class-count"><div><strong>{num(c.member_count)}</strong><span>班级成员</span></div><div><strong className={c.pending_count?'text-orange':''}>{num(c.pending_count)}</strong><span>{admin?'待处理成员':'待确认 / 审批'}</span></div></div><div className="class-card-footer">{deleted?<><button className="text-btn" disabled={c.can_restore===false} onClick={()=>setRemoval({target:c,restore:true})}>恢复班级</button><small className="class-restore-note">{c.can_restore===false?'教师或科目组不可用，暂不能恢复。':`删除于 ${date(c.deleted_at,true)}`}</small></>:<><button className="text-btn" onClick={()=>showMembers(c)}>查看成员 <Icon name="arrow" size={15}/></button>{!c.archived&&<button className="subtle-btn" onClick={()=>archive(c)}>归档</button>}{admin&&<button className="text-btn danger-text" onClick={()=>setRemoval({target:c,restore:false})}>删除班级</button>}</>}</div></section>)}</div>{!classes.length&&<section className="panel"><Empty text={deleted?'没有已删除班级':'还没有班级'} detail={deleted?'管理员删除的班级将在这里保留，可在条件满足时恢复。':'创建第一个班级，开始添加学生。'}/></section>}</DataState>
    {modal==='create'&&<Modal title="创建教学班级" description={admin?'管理员添加学生后直接成为正式成员，无需学生确认或教师审批。':'教师添加学生后，由学生确认教师可见范围再入班。'} onClose={()=>setModal(null)}><form onSubmit={create}><Field label="班级名称"><input required maxLength={80} value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="例如：机械 2027 备考一班"/></Field><div className="form-grid"><Field label="班级专业"><select required value={form.subject_group_id} onChange={e=>setForm({...form,subject_group_id:e.target.value})}><option value="">请选择专业</option>{groups.filter(g=>g.enabled!==false).map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select></Field><Field label="学期"><input required value={form.term} onChange={e=>setForm({...form,term:e.target.value})}/></Field></div>{admin&&<Field label="负责教师"><select required value={form.teacher_id} onChange={e=>setForm({...form,teacher_id:e.target.value})}><option value="">请选择教师</option>{(state.data?.users||[]).filter(u=>u.role==='teacher'&&u.enabled!==false).map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></Field>}<FormError error={error}/><div className="form-actions"><Button type="button" variant="secondary" onClick={()=>setModal(null)}>取消</Button><Button disabled={busy}>{busy?'创建中…':'创建班级'}</Button></div></form></Modal>}
    {modal==='members'&&<Modal wide title={selected.name} description={`${selected.teacher_name||'教师'} · ${selected.term||''}${selected.archived?' · 已归档，只读':''}`} onClose={closeMembers}>
      <div className="inline-note"><Icon name="shield" size={17}/><span>{admin?'管理员添加学生后直接成为正式成员，无需学生确认或教师审批。已有待确认成员也可直接设为正式成员或移出班级。':'管理员加入的学生已是正式成员。教师添加的学生仍需本人确认教师可见范围；待教师审批的成员可在此批准或拒绝。'}</span></div>
      {admin&&!selected.archived&&members&&(!memberSearchOpen?<Button type="button" className="class-member-search-open" variant="secondary" icon="plus" onClick={()=>setMemberSearchOpen(true)}>添加已有学生</Button>:<form className="class-add-member" onSubmit={addMember}><div className="class-member-search"><Field label="查找已有学生" hint="输入姓名或账号后按需搜索。"><input maxLength={100} autoFocus value={memberSearch} disabled={busy} placeholder="输入学生姓名或账号" onChange={event=>setMemberSearch(event.target.value)}/></Field><Field label="选择学生账号" hint="添加后立即成为该班正式成员。"><select required value={memberUserId} disabled={busy||memberSearchLoading||!memberSearch.trim()} onChange={e=>setMemberUserId(e.target.value)}><option value="">{memberSearchLoading?'正在查找…':!memberSearch.trim()?'请先输入姓名或账号':availableStudents.length?'选择学生账号':'没有匹配的可添加学生'}</option>{availableStudents.map(u=><option key={u.id} value={u.id}>{u.name}（{u.username}）</option>)}</select></Field><Button disabled={busy||memberSearchLoading||!memberUserId} icon="plus">{busy?'处理中…':'直接加入'}</Button>{memberCandidates.length===50&&<small>本次最多显示 50 个账号，请细化姓名或账号以便准确查找。</small>}{memberSearchError&&<small role="alert" className="danger-text">{memberSearchError}</small>}</div></form>)}
      <FormError error={error}/>
      {members?<Table headers={['姓名 / 账号','成员状态','操作']} empty={!members.length}>{members.map(m=><tr key={m.membership_id||m.id}><td><strong>{m.class_name||m.name||'未填写'}</strong><small className="table-sub">{m.username}</small></td><td><Badge status={m.status}>{admin&&['pending_confirmation','pending_approval'].includes(m.status)?'待处理':undefined}</Badge>{m.admin_enrolled&&m.status==='active'&&<small className="table-sub">管理员加入</small>}</td><td><div className="row-actions">
        {!selected.archived&&admin&&['pending_confirmation','pending_approval'].includes(m.status)&&<button disabled={busy} onClick={()=>updateMember(m,'active')}>设为正式成员</button>}
        {!selected.archived&&!admin&&m.status==='pending_approval'&&<><button disabled={busy} onClick={()=>updateMember(m,'active')}>批准</button><button disabled={busy} className="danger-text" onClick={()=>updateMember(m,'rejected')}>拒绝</button></>}
        {!selected.archived&&['active','pending_confirmation','pending_approval'].includes(m.status)&&<button disabled={busy} className="danger-text" onClick={()=>updateMember(m,'left')}>移出</button>}
        {(selected.archived||['left','rejected'].includes(m.status))&&<span className="subtle-text">—</span>}
      </div></td></tr>)}</Table>:!error&&<Loading/>}
    </Modal>}
    {removal&&<AdminRemovalModal kind="classes" {...removal} ui={{Modal,Field,Button,FormError}} onClose={()=>setRemoval(null)} onDone={async()=>{setRemoval(null);notify(removal.restore?'班级已恢复。':'班级已移至已删除列表。');await state.reload();}}/>}
  </>;
