  const currentUserUpdated=(updated,outcome)=>{if(updated.id!==user?.id)return;if(outcome.requiresRelogin){clearSession();setUser(null);setProfileOpen(false);notify(`登录账号已更新为 ${updated.username}，请使用新账号和原密码重新登录。`);navigate('dashboard');}else setUser(updated);};
  if(booting)return <div className="boot-screen"><span className="brand-icon"><Icon name="book" size={28}/></span><Loading/></div>;
  if(!user)return <><Login onLogin={u=>{setUser(u);navigate('dashboard');}}/>{toast&&<div className={`toast ${toast.type}`} role="status"><Icon name={toast.type==='error'?'message':'check'} size={18}/>{toast.message}<button onClick={()=>setToast(null)} aria-label="关闭提示"><Icon name="close" size={16}/></button></div>}</>;
